package dev.halloween;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.util.math.*;
import net.minecraft.item.*;
final class BarrelClientChecks {
 static boolean ready;static RailVehicleEntity ship,clientShip;static int id,wait,age,index,phase;static double originAngle;
 static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 static void register(){if(!Boolean.getBoolean("halloween.barrelTest"))return;
  ServerTickEvents.END_SERVER_TICK.register(server->{if(ready)return;var w=server.getOverworld();if(w.getPlayers().isEmpty())return;try{var base=new Vec3d(-1048.5,63,1088.5);var cp=new ChunkPos(BlockPos.ofFloored(base));for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)w.setChunkForced(cp.x+x,cp.z+z,true);if(++wait<80)return;for(var old:RailVehicleEntity.nearby(w,new Box(base,base).expand(100)))old.discard();ship=NavalContent.spawn(w,2,base,0);require(ship!=null,"ship spawned");id=ship.getId();for(int i=0;i<8;i++)ship.naval().barrels[i].setStack(0,new ItemStack(Items.EMERALD,i+1));var out=net.minecraft.storage.NbtWriteView.create(net.minecraft.util.ErrorReporter.EMPTY,w.getRegistryManager());ship.writeData(out);var clone=NavalContent.BRIG_ENTITY.create(w,net.minecraft.entity.SpawnReason.LOAD);clone.readData(net.minecraft.storage.NbtReadView.create(net.minecraft.util.ErrorReporter.EMPTY,w.getRegistryManager(),out.getNbt()));for(int i=0;i<8;i++)require(clone.naval().barrels[i].size()==27&&clone.naval().barrels[i].getStack(0).getCount()==i+1,"barrel "+i+" persists independently");clone.discard();place(server,0);ready=true;}catch(Throwable e){org.slf4j.LoggerFactory.getLogger("barrel-test").error("FAIL setup",e);server.stop(false);}});
  ClientTickEvents.END_CLIENT_TICK.register(c->{if(!ready||phase<0||c.player==null||c.world==null)return;c.options.pauseOnLostFocus=false;if(c.currentScreen instanceof net.minecraft.client.gui.screen.GameMenuScreen)c.setScreen(null);if(clientShip==null)clientShip=c.world.getEntityById(id) instanceof RailVehicleEntity t?t:null;if(clientShip==null)return;age++;try{if(phase==0){var center=RailGeometry.rotate(NavalGeometry.barrelBoxes(2).get(index).getCenter(),clientShip.getYaw()).add(clientShip.getEntityPos());var d=center.subtract(c.player.getEyePos());c.player.setYaw((float)Math.toDegrees(Math.atan2(-d.x,d.z)));c.player.setPitch((float)-Math.toDegrees(Math.atan2(d.y,d.horizontalLength())));if(age==25){var hit=c.player.getCrosshairTarget(1,c.player);require(hit instanceof net.minecraft.util.hit.EntityHitResult e&&e.getEntity()==clientShip,"barrel targeted through actual crosshair");c.interactionManager.interactEntity(c.player,clientShip,net.minecraft.util.Hand.MAIN_HAND);phase++;age=0;}}
   else if(phase==1&&c.currentScreen instanceof net.minecraft.client.gui.screen.ingame.GenericContainerScreen){require(c.player.currentScreenHandler.slots.size()==63,"barrel has 27 storage slots");require(c.player.currentScreenHandler.getSlot(0).getStack().getCount()==index+1,"correct independent barrel contents "+index);if(index==2)net.minecraft.client.util.ScreenshotRecorder.saveScreenshot(c.runDirectory,"ship-barrel-container.png",c.getFramebuffer(),1,t->{});c.interactionManager.clickSlot(c.player.currentScreenHandler.syncId,0,0,net.minecraft.screen.slot.SlotActionType.QUICK_MOVE,c.player);phase++;age=0;}
   else if(phase==2&&age>12){require(c.player.currentScreenHandler.getSlot(0).getStack().isEmpty(),"real quick move removed contents");c.player.closeHandledScreen();org.slf4j.LoggerFactory.getLogger("barrel-test").info("PASS barrel {}: actual 27-slot UI, unique contents, real item transfer",index+1);index++;if(index==8){int count=c.player.getInventory().count(Items.EMERALD);require(count>=36,"all eight barrels transferred to player without loss");require(Math.abs(clientShip.wheelAngle(1))>30,"rudder animation synchronized to client");org.slf4j.LoggerFactory.getLogger("barrel-test").info("PASS all 8 barrels, upper/lower, real UI transfers, independent serialization and synchronized animated helm");phase=-1;c.scheduleStop();return;}int next=index;c.getServer().execute(()->place(c.getServer(),next));phase=0;age=0;}
   if(age>120)throw new AssertionError("phase timeout "+phase+" barrel="+index);
  }catch(Throwable e){phase=-1;org.slf4j.LoggerFactory.getLogger("barrel-test").error("FAIL",e);c.scheduleStop();}});
 }
 static void place(net.minecraft.server.MinecraftServer server,int i){var p=server.getOverworld().getPlayers().getFirst();p.stopRiding();p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.setHealth(20);p.getAbilities().flying=false;p.sendAbilitiesUpdate();if(i==4){ship.setYaw(20);ship.naval().rudder=.7f;ship.naval().lastControl=Long.MAX_VALUE;ship.rudder(.7f);}var b=NavalGeometry.barrelBoxes(2).get(i).getCenter();var spot=RailGeometry.rotate(new Vec3d(0,.95,b.z),ship.getYaw()).add(ship.getEntityPos());p.networkHandler.requestTeleport(spot.x,spot.y,spot.z,0,0);}
}
